.wsbusyboard__ime{display:flex;align-items:center;gap:10px}.wsbusyboard__av{flex:0 0 34px;width:34px;height:34px;border-radius:50%;background:#cdeee8;border:1px solid #12806f;color:#12806f;font-style:normal;font-weight:800;font-size:14px;display:inline-flex;align-items:center;justify-content:center}
div.wsbusyboard__pog{text-align:center;border:1px solid rgba(18,128,111,.35);border-radius:16px;transition:transform .2s,box-shadow .2s}div.wsbusyboard__pog:hover{transform:translateY(-3px);box-shadow:0 14px 30px rgba(18,128,111,.22)}div.wsbusyboard__pog>strong,div.wsbusyboard__pog>span:not(.wsbusyboard__pi){display:block}
