.wsbusyboard__kar.wsbusyboard__kar4{grid-auto-columns:calc((100% - 66px)/4)}@media (max-width:860px){.wsbusyboard__kar.wsbusyboard__kar4{grid-auto-columns:calc((100% - 22px)/2)}}@media (max-width:560px){.wsbusyboard__kar.wsbusyboard__kar4{grid-auto-columns:78%}}
